/**
 * ServBazaar mark, inlined as data URIs — site-engine renders the marketing
 * site as plain HTML strings with no static asset pipeline of its own, so
 * embedding is simpler than standing up an R2-backed asset route for two
 * small images.
 */
// og:image needs a real fetchable URL, not a data URI — social-share
// crawlers (Facebook/WhatsApp/Twitter link previews) fetch it separately
// and generally won't resolve data: URIs. Served via GET /og-image.jpg in
// index.ts instead of inlined directly into a meta tag like the favicon is.
export const FAVICON_DATA_URI = "data:image/png;base64,";
export const LOGO_DATA_URI = "data:image/png;base64,";

export const OG_IMAGE_BASE64 = "";

// Square mark for Organization.logo JSON-LD (Google recommends a real,
// fetchable, reasonably-sized square image) — served via GET /logo.png.
export const SQUARE_LOGO_BASE64 = "";
